  def initialize
    @store = {}
  end

  # Set value at a given index.
  def []=(index, value)
    @store[index] = value
  end

  # Retrieve value at the given index, or nil if never set.
  def [](index)
    @store[index]
  end

  # Iterate over stored values in ascending index order.
  def each
    @store.keys.sort.each { |index| yield @store[index] }
  end
end
