class SparseArray
  include Enumerable

  def initialize
    @store = {}
  end

  def []=(index, value)
    @store[index] = value
  end

  def [](index)
    @store[index]
  end

  def each
    return enum_for(:each) unless block_given?

    @store.keys.sort.each do |key|
      yield @store[key]
    end
  end
end
